#include <fcntl.h>   // open、O_RDONLY
#include <unistd.h>  // close
#include <cstdio>    // printf、perror

int main() {
    int fd = open("gpu-kernel-lab/results/raw/2026-10-27-fd-input.txt", O_RDONLY);
    if (fd < 0) {
        std::perror("open");
        return 1;
    }

    std::printf("fd=%d\n", fd);
    char buf[4];

ssize_t n = read(fd, buf, sizeof(buf));

if (n < 0) {
    std::perror("read");
    close(fd);
    return 1;
}

std::printf("read=%zd\n", n);

    if (close(fd) < 0) {
        std::perror("close");
        return 1;
    }

    return 0;
}
